static int dm_test_uclass_devices_find_by_name ( struct unit_test_state * uts ) { struct udevice * finddev ; struct udevice * testdev ; int findret , ret ; for ( ret = uclass_find_first_device ( UCLASS_TEST_FDT , & testdev ) ; testdev ; ret = uclass_find_next_device ( & testdev ) ) { ut_assertok ( ret ) ; ut_assertnonnull ( testdev ) ; findret = uclass_find_device_by_name ( UCLASS_TEST_FDT , testdev -> name , & finddev ) ; ut_assertok ( findret ) ; ut_asserteq_str ( testdev -> name , finddev -> name ) ; ut_asserteq_ptr ( testdev , finddev ) ; } return 0 ; } 